import { vec3 } from 'gl-matrix';
import { utilities as csUtils } from '@cornerstonejs/core';
import { getBoundingBoxAroundShapeIJK } from './boundingBox/index.js';
const { asUnitNormal, getMembershipHalfWidth, getVoxelThicknessAlongNormal, resolveReferencePlaneThickness, sampleVoxelsInShape, } = csUtils.voxelSlab;
export default function sampleAreaAnnotationVoxels({ annotation, image, voxelManager, points, boundsMargin = 0, createShape, planePoint: planePointOverride, minimumPoints = 3, onSample, storePointData, }) {
    const viewPlaneNormal = resolveAnnotationNormal(annotation?.metadata);
    if (!voxelManager ||
        !image ||
        !viewPlaneNormal ||
        !(points?.length >= minimumPoints)) {
        return [];
    }
    const planePoint = planePointOverride ?? points[0];
    const { dimensions, direction, spacing, origin, imageData } = image;
    const volume = { dimensions, direction, spacing, origin };
    const voxelThickness = getVoxelThicknessAlongNormal(volume, viewPlaneNormal);
    const referencePlaneThickness = resolveReferencePlaneThickness(annotation.metadata?.planeRestriction?.referencePlaneThickness, voxelThickness);
    const shape = createShape({ volume, planePoint, viewPlaneNormal });
    if (!shape) {
        return [];
    }
    const slabThickness = shape.getRequiredThickness() || referencePlaneThickness;
    return sampleVoxelsInShape({
        volume,
        planePoint,
        viewPlaneNormal,
        referencePlaneThickness: slabThickness,
        bounds: getShapeIndexBounds(points, volume, imageData, viewPlaneNormal, getMembershipHalfWidth(slabThickness, voxelThickness), boundsMargin),
        getShapeRuns: shape.getRuns,
        voxelManager,
        onSample,
        storePointData,
    });
}
function resolveAnnotationNormal(metadata) {
    const recorded = metadata?.viewPlaneNormal;
    if (recorded && vec3.squaredLength(recorded) > 0) {
        return asUnitNormal(recorded);
    }
    const { inPlaneVector1, inPlaneVector2 } = metadata?.planeRestriction ?? {};
    if (!inPlaneVector1 || !inPlaneVector2) {
        return undefined;
    }
    const normal = vec3.cross(vec3.create(), inPlaneVector1, inPlaneVector2);
    return vec3.squaredLength(normal) > 0
        ? asUnitNormal(normal)
        : undefined;
}
export function getShapeIndexBounds(points, volume, imageData, viewPlaneNormal, halfWidth, margin = 0) {
    const { dimensions, direction, spacing } = volume;
    const indexPoints = points.map((point) => imageData.worldToIndex(point));
    const boundingBox = getBoundingBoxAroundShapeIJK(indexPoints);
    return [0, 1, 2].map((axis) => {
        const axisVector = direction.slice(axis * 3, axis * 3 + 3);
        const dilation = Math.ceil((margin +
            halfWidth * Math.abs(vec3.dot(axisVector, viewPlaneNormal))) /
            spacing[axis]) + 1;
        return [
            Math.max(0, Math.floor(boundingBox[axis][0]) - dilation),
            Math.min(dimensions[axis] - 1, Math.ceil(boundingBox[axis][1]) + dilation),
        ];
    });
}
